impl AntiProjectOrthogonallyOnto<MultiVector> for FlatOrigin {
    type Output = MultiVector;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div
    //      f32       37       55        0
    //    simd2        0        1        0
    //    simd3       12       18        0
    //    simd4       11       11        0
    // Totals...
    // yes simd       60       85        0
    //  no simd      117      155        0
    fn anti_project_orthogonally_onto(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        let anti_wedge_g0 = Simd32x2::from([self[e45] * other[e45], 1.0]) * Simd32x2::from([-1.0, 0.0]);
        let anti_wedge_g1 = Simd32x3::from(0.0).with_w(other.group1().wxyz()[0] * self[e45]);
        let anti_wedge_g2 = self[e45] * other[e5] * -1.0;
        let anti_wedge_g3 = Simd32x3::from(0.0).with_w(other.group0().yx()[1] * self[e45]);
        return MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([
                anti_wedge_g0[0] * other[scalar],
                (anti_wedge_g2 * other[e1234])
                    + (anti_wedge_g0[0] * other[e12345])
                    + (anti_wedge_g0[1] * other[scalar])
                    + (anti_wedge_g1[0] * other[e4235])
                    + (anti_wedge_g1[1] * other[e4315])
                    + (anti_wedge_g1[2] * other[e4125])
                    + (anti_wedge_g1[3] * other[e3215])
                    - (anti_wedge_g3[0] * other[e235])
                    - (anti_wedge_g3[1] * other[e315])
                    - (anti_wedge_g3[2] * other[e125])
                    - (anti_wedge_g3[3] * other[e321]),
            ]),
            // e1, e2, e3, e4
            (anti_wedge_g1 * Simd32x4::from(other[scalar])) + (Simd32x4::from(anti_wedge_g0[0]) * other.group1()),
            // e5
            (anti_wedge_g2 * other[scalar]) + (anti_wedge_g0[0] * other[e5]),
            // e41, e42, e43, e45
            (anti_wedge_g3 * Simd32x4::from(other[scalar]))
                + (Simd32x4::from(anti_wedge_g0[0]) * other.group3())
                + (anti_wedge_g1.xyz() * other.group1().www()).with_w(anti_wedge_g2 * other[e4])
                - (Simd32x4::from(anti_wedge_g1[3]) * other.group1().xyz().with_w(other[e5])),
            // e15, e25, e35
            (Simd32x3::from(anti_wedge_g2) * other.group1().xyz()) + (Simd32x3::from(anti_wedge_g0[0]) * other.group4()) - (Simd32x3::from(other[e5]) * anti_wedge_g1.xyz()),
            // e23, e31, e12
            (Simd32x3::from(anti_wedge_g0[0]) * other.group5()) + (anti_wedge_g1.zxy() * other.group1().yzx()) - (anti_wedge_g1.yzx() * other.group1().zxy()),
            // e415, e425, e435, e321
            Simd32x4::from([
                (anti_wedge_g2 * other[e41]) + (anti_wedge_g1[3] * other[e15]) + (anti_wedge_g3[0] * other[e5]),
                (anti_wedge_g2 * other[e42]) + (anti_wedge_g1[3] * other[e25]) + (anti_wedge_g3[1] * other[e5]),
                (anti_wedge_g2 * other[e43]) + (anti_wedge_g1[3] * other[e35]) + (anti_wedge_g3[2] * other[e5]),
                -(anti_wedge_g1[0] * other[e23]) - (anti_wedge_g1[1] * other[e31]) - (anti_wedge_g1[2] * other[e12]),
            ]) + (Simd32x4::from(anti_wedge_g0[0]) * other.group6())
                - (other.group1().xyzy() * anti_wedge_g3.www().with_w(0.0))
                - (anti_wedge_g1.xyz() * other.group3().www()).with_w(0.0),
            // e423, e431, e412
            (Simd32x3::from(anti_wedge_g0[0]) * other.group7())
                + (Simd32x3::from(anti_wedge_g1[3]) * other.group5())
                + (anti_wedge_g1.zxy() * other.group3().yzx())
                + (anti_wedge_g3.yzx() * other.group1().zxy())
                - (anti_wedge_g1.yzx() * other.group3().zxy())
                - (anti_wedge_g3.zxy() * other.group1().yzx()),
            // e235, e315, e125
            (Simd32x3::from(anti_wedge_g2) * other.group5()) + (Simd32x3::from(anti_wedge_g0[0]) * other.group8()) + (other.group4().zxy() * anti_wedge_g1.yzx())
                - (other.group4().yzx() * anti_wedge_g1.zxy()),
            // e1234, e4235, e4315, e4125
            Simd32x4::from([
                -(anti_wedge_g1[2] * other[e412]) - (anti_wedge_g1[3] * other[e321]) - (anti_wedge_g3[1] * other[e31]) - (anti_wedge_g3[2] * other[e12]),
                (anti_wedge_g2 * other[e423]) + (anti_wedge_g1[1] * other[e435]) + (anti_wedge_g3[1] * other[e35]) + (anti_wedge_g3[3] * other[e23]),
                (anti_wedge_g2 * other[e431]) + (anti_wedge_g1[2] * other[e415]) + (anti_wedge_g3[2] * other[e15]) + (anti_wedge_g3[3] * other[e31])
                    - (anti_wedge_g1[0] * other[e435]),
                (anti_wedge_g2 * other[e412]) + (anti_wedge_g1[0] * other[e425]) + (anti_wedge_g3[0] * other[e25]) + (anti_wedge_g3[3] * other[e12])
                    - (anti_wedge_g1[1] * other[e415]),
            ]) + (Simd32x4::from(anti_wedge_g0[0]) * other.group9())
                - (Simd32x4::from([other[e23], other[e25], other[e5], other[e5]]) * anti_wedge_g3.xz().with_zw(0.0, 0.0))
                - (Simd32x4::from([other[e423], other[e235], anti_wedge_g3[0], anti_wedge_g3[1]]) * anti_wedge_g1.xw().with_zw(other[e35], other[e15]))
                - (Simd32x4::from([other[e431], other[e425], anti_wedge_g1[3], anti_wedge_g1[3]]) * anti_wedge_g1.yz().with_zw(other[e315], other[e125])),
            // e3215
            (anti_wedge_g2 * other[e321])
                + (anti_wedge_g0[0] * other[e3215])
                + (anti_wedge_g1[0] * other[e235])
                + (anti_wedge_g1[1] * other[e315])
                + (anti_wedge_g1[2] * other[e125]),
        );
    }
}
