impl AntiProjectOrthogonallyOnto<MultiVector> for RoundPointAtOrigin {
    type Output = MultiVector;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div
    //      f32       22       38        0
    //    simd2        0        1        0
    //    simd3       10       16        0
    //    simd4        8        8        0
    // Totals...
    // yes simd       40       63        0
    //  no simd       84      120        0
    fn anti_project_orthogonally_onto(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        let right_anti_dual_g0 = other.group0().yx() * Simd32x2::from([-1.0, 1.0]);
        let anti_wedge_g0_x = -(other.group1().wxyz()[0] * self[e5]) - (other[e5] * self[e4]);
        let anti_wedge_g1 = Simd32x3::from(0.0).with_w(right_anti_dual_g0[1] * self[e4]);
        let anti_wedge_g2 = right_anti_dual_g0[1] * self[e5];
        return MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([
                anti_wedge_g0_x * other[scalar],
                (anti_wedge_g0_x * other[e12345])
                    + (anti_wedge_g2 * other[e1234])
                    + (anti_wedge_g1[0] * other[e4235])
                    + (anti_wedge_g1[1] * other[e4315])
                    + (anti_wedge_g1[2] * other[e4125])
                    + (anti_wedge_g1[3] * other[e3215]),
            ]),
            // e1, e2, e3, e4
            (anti_wedge_g1 * Simd32x4::from(other[scalar])) + (Simd32x4::from(anti_wedge_g0_x) * other.group1()),
            // e5
            (anti_wedge_g0_x * other[e5]) + (anti_wedge_g2 * other[scalar]),
            // e41, e42, e43, e45
            (Simd32x4::from(anti_wedge_g0_x) * other.group3()) + (anti_wedge_g1.xyz() * other.group1().www()).with_w(anti_wedge_g2 * other[e4])
                - (Simd32x4::from(anti_wedge_g1[3]) * other.group1().xyz().with_w(other[e5])),
            // e15, e25, e35
            (Simd32x3::from(anti_wedge_g0_x) * other.group4()) + (Simd32x3::from(anti_wedge_g2) * other.group1().xyz()) - (Simd32x3::from(other[e5]) * anti_wedge_g1.xyz()),
            // e23, e31, e12
            (Simd32x3::from(anti_wedge_g0_x) * other.group5()) + (anti_wedge_g1.zxy() * other.group1().yzx()) - (anti_wedge_g1.yzx() * other.group1().zxy()),
            // e415, e425, e435, e321
            Simd32x4::from([
                (anti_wedge_g2 * other[e41]) + (anti_wedge_g1[3] * other[e15]),
                (anti_wedge_g2 * other[e42]) + (anti_wedge_g1[3] * other[e25]),
                (anti_wedge_g2 * other[e43]) + (anti_wedge_g1[3] * other[e35]),
                -(anti_wedge_g1[0] * other[e23]) - (anti_wedge_g1[1] * other[e31]) - (anti_wedge_g1[2] * other[e12]),
            ]) + (Simd32x4::from(anti_wedge_g0_x) * other.group6())
                - (anti_wedge_g1.xyz() * other.group3().www()).with_w(0.0),
            // e423, e431, e412
            (Simd32x3::from(anti_wedge_g0_x) * other.group7()) + (Simd32x3::from(anti_wedge_g1[3]) * other.group5()) + (anti_wedge_g1.zxy() * other.group3().yzx())
                - (anti_wedge_g1.yzx() * other.group3().zxy()),
            // e235, e315, e125
            (Simd32x3::from(anti_wedge_g0_x) * other.group8()) + (Simd32x3::from(anti_wedge_g2) * other.group5()) + (other.group4().zxy() * anti_wedge_g1.yzx())
                - (other.group4().yzx() * anti_wedge_g1.zxy()),
            // e1234, e4235, e4315, e4125
            Simd32x4::from([
                -(anti_wedge_g1[2] * other[e412]) - (anti_wedge_g1[3] * other[e321]),
                (anti_wedge_g2 * other[e423]) + (anti_wedge_g1[1] * other[e435]),
                (anti_wedge_g2 * other[e431]) + (anti_wedge_g1[2] * other[e415]) - (anti_wedge_g1[0] * other[e435]),
                (anti_wedge_g2 * other[e412]) + (anti_wedge_g1[0] * other[e425]) - (anti_wedge_g1[1] * other[e415]),
            ]) + (Simd32x4::from(anti_wedge_g0_x) * other.group9())
                - (Simd32x4::from([other[e423], other[e235], 0.0, 0.0]) * anti_wedge_g1.xw().with_zw(other[e35], other[e15]))
                - (Simd32x4::from([other[e431], other[e425], anti_wedge_g1[3], anti_wedge_g1[3]]) * anti_wedge_g1.yz().with_zw(other[e315], other[e125])),
            // e3215
            (anti_wedge_g0_x * other[e3215])
                + (anti_wedge_g2 * other[e321])
                + (anti_wedge_g1[0] * other[e235])
                + (anti_wedge_g1[1] * other[e315])
                + (anti_wedge_g1[2] * other[e125]),
        );
    }
}
